#!/usr/bin/env python3
"""Pin Wake of Fire's distinct actor, maker/wave and current local table routes."""
import argparse,csv,hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def build(check=False):
 source=ROOT/'tools/reference/d2r-named-equipment';manifest=json.loads((source/'sources.json').read_text());tables={};pins={}
 for name in ['skills','missiles','monstats']:
  p=source/'json'/f'{name}.json';pins[name]=hashlib.sha256(p.read_bytes()).hexdigest();assert pins[name]==manifest['files'][f'json/{name}.json']['sha256'];tables[name]=json.loads(p.read_bytes())
 player=tables['skills']['262'];actor=tables['skills']['281'];monster=tables['monstats']['wakeofdestruction'];maker=tables['missiles']['wake of destruction maker'];wave=tables['missiles']['wake of destruction']
 raw=ROOT/'.local/research/d2r-3.3.93847/skills.txt';local={r['skill']:r for r in csv.DictReader(raw.read_text(encoding='utf-8-sig').splitlines(),delimiter='\t') if r.get('skill')};counts={}
 for row in [player,actor]:
  actual=local[row['skill']];count=0
  for key,value in row.items():
   if key in actual and not key.startswith('*') and key!='lineNumber':assert str(value)==actual[key],(row['skill'],key,value,actual[key]);count+=1
  counts[row['skill']]=count
 assert player['srvdofunc']==45 and actor['srvdofunc']==125 and player['petmax']==5 and player['mana']==13 and player['Param1']==actor['Param8']==5
 assert maker['pSrvDoFunc']==31 and maker['Skill']==wave['Skill']=='Wake of Fire Sentry' and not maker.get('MissileSkill') and not wave.get('MissileSkill')
 evidence=json.loads((ROOT/'tools/reference/d2r-local-missile-data-evidence.json').read_text());assert len([n for n in evidence['selectedRows'] if n.startswith('wake of destruction')])==2
 e=dict(referenceVersion='3.3.93847',talentId='assassin.wakeoffire',sourceId=262,status='Current data and source routes prepared;native learned handler disabled',installed=False,handlerEnabled=False,pinnedHashes=pins,localSkills=dict(path=str(raw.relative_to(ROOT)),sha256=hashlib.sha256(raw.read_bytes()).hexdigest(),comparedFields=counts),localMissileEvidence='tools/reference/d2r-local-missile-data-evidence.json',localAnimationEvidence='tools/reference/d2r-local-sentry-animation-evidence.json',currentObservations='tools/reference/wake-of-fire-current-observations.json',skill=player,actorSkill=actor,monster=monster,missiles={'maker':maker,'wave':wave},reuse=['Existing do45trap creation, five-slot replacement ordering, saved sentry bodies, emergence, AI/shot/mode/target/path, owner difficulty rescaling and offline/travel contracts;match each contract before reuse.','Shared current elemental getters, source-zero damage creator, fire resistance/pierce/immunity and source missile stepping/collision. Charged Bolt Sentry lightning-specific passive and damage routes must be extended explicitly.','Shared D2Common_10234path flag gate and ordered source steps from Poison Javelin;do not substitute a time-only emission loop.'],established=['Current player skill262spends13mana,uses attack-rate S2and creates wakeofdestruction with shared trap limit5. NPC skill281has5shots and fires maker517using do125.','Maker517uses do31,velocity10and range25+2*rank. Each movement-flag update emits opposite wave518children from its origin using the stored perpendicular aim. Wave518uses do1,velocity8,range20,Size1and shared four-frame NextHit data.','Both missile rows select skill262for elemental damage;stored actor skill281must not override that table Skill. Source-damage0excludes ordinary weapon/typed/critical/drain. Hard Fire Trauma/Inferno synergies are10percent each per rank.','Current player passive slots inherit fire immunity pierce,fire resistance pierce and fire mastery. These are distinct from the installed lightning-specific sentry projection.'],required=['Current local e9S2is2frameswithmarker1atframe1;lgS2is15frameswithmarker2atframe0. Reuse15frame S1only where the complete rate/mode context matches;trace the separate S2event routing rather than copying lightning shot timing.','Compose complete do125/do31/factory/target setter and path gate control flow,including missing owner/record/factory and zero-vector contexts.','Compose fire endpoint getters/mastery/synergies and nested maker/wave creators. Trace DamageRate205,LastCollide,NextHit and source owner-death/stat cleanup before adapting them.','Reuse shared actor creation,stat rescaling and five-trap limit without overriding the existing approved old-facet/offline behavior. Resolve any shared retirement/GUID dependency individually and continue unaffected work.','Verify actual world placement,targets,shots,continuous connected damage,source clocks,gear/rank,inputs/lifecycle and two world reloads before enabling.'],assets=dict(effects='Final S1/S2/NU/DT actor, fire maker/wave travel/impact and audio remain pending;use explicitly identified placeholders during mechanics.',icons='Talent/right/quick icons remain in the separate240row inventory.'),next='Compose the source fan producer and fire packet,then connect supported sentry components. No class completion certificate.')
 out=ROOT/'tools/reference/wake-of-fire-preflight.json';encoded=json.dumps(e,indent=2)+'\n'
 if check:assert out.read_text()==encoded,'Wake of Fire preflight stale'
 else:out.write_text(encoded)
 print('Wake of Fire:current skill262/actor281and maker517/wave518routes pinned;local skill/missile corroboration retained;handler disabled.')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');build(p.parse_args().check)
